using Unity.Mathematics;
using UnityEngine;

namespace ZE.MechBattle.Views
{
    // generated by GoogleAI
    public readonly struct CameraFrustrum2D
    {
        public readonly float3 CameraPos;      // Реальная 3D-позиция камеры (transform.position)
        public readonly float3 CameraForward;  // Реальный 3D-вектор вперед (transform.forward)
        public readonly float3 CameraRight;    // Реальный 3D-вектор вправо (transform.right)
        public readonly float3 CameraUp;       // Реальный 3D-вектор вверх (transform.up)

        public readonly float TanHalfVertFov;  // math.tan(math.radians(cam.fieldOfView * 0.5f))
        public readonly float TanHalfHorizFov; // TanHalfVertFov * cam.aspect
        public readonly float NearClip;
        public readonly float FarClip;
        public readonly float Padding;         // Запас на радиус гекса + высоту юнитов (например, HexEdge * 1.5f)

        public CameraFrustrum2D(Camera camera, float padding)
        {
            var transform = camera.transform;

            CameraPos = transform.position;
            CameraForward = transform.forward;
            CameraRight = transform.right;
            CameraUp = transform.up;

            TanHalfVertFov = math.tan(math.radians(camera.fieldOfView * 0.5f));
            TanHalfHorizFov = TanHalfVertFov * camera.aspect;

            NearClip = camera.nearClipPlane;
            FarClip = camera.farClipPlane;
            Padding = padding;
        }
    }
}
